import {drugReference} from './medication-data.js';
export const shockProtocols=[
 {id:'C300',label:'VF / pulseless VT',context:'Adult · no pulse',page:75,mode:'UNSYNCHRONIZED',initial:'MAX',steps:['MAX','MAX'],stepLabels:['Next shock','Further shocks'],note:'Use the maximum energy recommended by the defibrillator manufacturer for each indicated shock.'},
 {id:'C303',label:'Wide complex · unstable',context:'Adult · with pulse',page:79,mode:'SYNCHRONIZED',initial:'100',steps:['200','300','360'],note:'Listed joules or biphasic equivalent. If the rhythm recurs, use the previously successful energy; if unsuccessful, use the next higher setting.',syncNote:'Synchronize unless it is impossible (for example, an irregular rhythm), per C303.',sedation:'versed-cardioversion'},
 {id:'C306',label:'Narrow complex · unstable',context:'Adult · with pulse',page:82,mode:'SYNCHRONIZED',sedation:'versed-cardioversion-narrow'}
];
export function selectedShockProtocol(fields){return shockProtocols.find(p=>p.id===fields['shock-protocol'])||null;}
export function shockPlan(fields){const protocol=selectedShockProtocol(fields);if(!protocol)return null;if(protocol.id!=='C306')return protocol;
 const rhythm=['regular','irregular-biphasic','irregular-monophasic'].includes(fields['shock-narrow-rhythm'])?fields['shock-narrow-rhythm']:'regular';
 const plans={regular:{initial:'50–100',steps:['100','200','300','360']},'irregular-biphasic':{initial:'120–200',steps:['200','300','360']},'irregular-monophasic':{initial:'200',steps:['300','360']}};
 return {...protocol,...plans[rhythm],rhythm,note:'After an unsuccessful shock, use the next higher energy than the previous shock. Skip settings already reached; never step down.'};
}
export function adultShockSedation(fields){const selected=selectedShockProtocol(fields);return selected?.sedation?drugReference.find(m=>m.id==='midazolam').pathways.find(p=>p.id===selected.sedation):null;}
const step=(dose,label)=>`<div class="shock-energy-step"><span>${label}</span><strong>${dose}${dose==='MAX'?'':'<small>J</small>'}</strong></div>`;
function sedationGuide(fields,source,icon){const path=adultShockSedation(fields);if(!path)return `<button class="shock-sedation-link" data-page="sedation">${icon('syringe')}<span><b>Open sedation guide</b><small>Indication-specific doses</small></span>${icon('arrow')}</button>`;
 const recipe=path.recipes[0];return `<aside class="shock-sedation" aria-labelledby="shock-sedation-title"><div class="shock-sedation-heading"><h3 id="shock-sedation-title">Adult sedation · ${path.code}</h3>${source(path.code+' · SEDATION',path.page)}</div><div class="shock-sedation-dose"><div><b>Midazolam / Versed</b><strong>${recipe.low}–${recipe.high} <small>${recipe.unit}</small></strong></div><div class="shock-sedation-routes">${recipe.route.split(' / ').map(route=>`<span>${route}</span>`).join('')}</div></div><p><b>Maximum ${recipe.totalMax} mg total.</b> Titrate to effect (slurred speech) for a conscious patient without altered mental status. Do not delay urgent cardioversion.</p><button class="shock-sedation-link" data-page="sedation" data-cardio-sedation="${path.id}">${icon('syringe')}<span><b>Open sedation & dose guide</b><small>${path.code} · adult cardioversion</small></span>${icon('arrow')}</button></aside>`;}
export function defibGuide(fields,source,icon){const selected=shockPlan(fields);return `<section class="check-section priority-section shock-guide" data-priority="blue" aria-labelledby="shock-guide-title"><h2 id="shock-guide-title"><span>01</span>Shock dosing guide <small>Adult · age 16+</small></h2><div class="shock-guide-content"><div class="shock-protocol-choices" role="group" aria-label="Select shock protocol">${shockProtocols.map(p=>`<button data-shock-protocol="${p.id}" aria-pressed="${selected?.id===p.id}"><b>${p.id}</b><span>${p.label}</span><small>${p.context}</small></button>`).join('')}</div>${selected?`<div class="shock-plan" aria-live="polite"><div class="shock-plan-heading"><h3>${selected.label}</h3><span class="shock-mode ${selected.id==='C300'?'unsynchronized':''}">${selected.mode}</span></div>${selected.id==='C306'?`<div class="shock-rhythm-choices" role="group" aria-label="Narrow complex rhythm and waveform">${[['regular','Regular'],['irregular-biphasic','Irregular · biphasic'],['irregular-monophasic','Irregular · monophasic']].map(([id,label])=>`<button data-shock-rhythm="${id}" aria-pressed="${selected.rhythm===id}">${label}</button>`).join('')}</div>`:''}${selected.id==='C306'?`<div class="shock-start-energy">${step(selected.initial,'Initial shock')}</div><b class="shock-escalation-label">Then move to the next higher setting</b>`:''}<div class="shock-energy-sequence">${selected.id==='C306'?'':step(selected.initial,'Initial shock')}${selected.steps.map((dose,i)=>step(dose,selected.stepLabels?.[i]||(selected.id==='C306'?'Next higher option':`Shock ${i+2}`))).join('')}</div><p class="shock-dose-note">${selected.note}</p>${selected.syncNote?`<p class="shock-sync-note">${selected.syncNote}</p>`:''}<div class="shock-dose-source">${source('ENERGY · '+selected.id,selected.page)}</div></div>`:'<p class="shock-select-hint">Select a protocol to see its shock doses.</p>'}${sedationGuide(fields,source,icon)}</div></section>`;}
export function bindDefibGuide(getState,save,render){document.addEventListener('click',e=>{const button=e.target.closest('[data-shock-protocol],[data-shock-rhythm]');if(!button)return;const fields=getState().fields;if(button.dataset.shockProtocol){if(!shockProtocols.some(p=>p.id===button.dataset.shockProtocol))return;fields['shock-protocol']=button.dataset.shockProtocol;}else{if(!['regular','irregular-biphasic','irregular-monophasic'].includes(button.dataset.shockRhythm))return;fields['shock-narrow-rhythm']=button.dataset.shockRhythm;}save();const y=window.scrollY;render();window.scrollTo(0,y);const selector=button.dataset.shockProtocol?`[data-shock-protocol="${button.dataset.shockProtocol}"]`:`[data-shock-rhythm="${button.dataset.shockRhythm}"]`;document.querySelector(selector)?.focus({preventScroll:true});});}
